                        q.append((yy,xx))
            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            boxes.append((min(rs), min(cs), max(rs)-min(rs)+1, max(cs)-min(cs)+1))
    boxes = tuple(sorted(boxes))
    selected = _DEMOS.get((h, w, boxes))
